import type { BaseMessage, Channel } from './message.js';
import type { RelayoEvent } from './events.js';

export interface SendResult {
  /** Relayo's own id; stable across providers and failover. */
  messageId: string;
  providerMessageId?: string;
  provider: string;
  status: 'queued' | 'sent';
  /** Recipients the provider refused synchronously while accepting the rest; the message did not go to them. */
  rejectedRecipients?: string[];
}

/** Context the core hands to a driver on every send. */
export interface SendContext {
  /** Id generated by the core; drivers should attach it to the provider message so webhooks can map back. */
  messageId: string;
}

export interface DriverCapabilities {
  batch: boolean;
  attachments: boolean;
  scheduling: boolean;
  /** Opens and clicks. */
  tracking: boolean;
  webhooks: boolean;
}

export interface WebhookRequest {
  headers: Record<string, string | string[] | undefined>;
  /** Parsed body, if the framework already parsed it. */
  body: unknown;
  /** Raw body, needed by providers that sign the exact bytes. */
  rawBody?: string | Uint8Array;
  /**
   * Name of the driver the webhook belongs to (e.g. from the endpoint path: `/webhooks/ses`).
   * Required to route webhooks reliably when the channel uses `failover()`.
   */
  provider?: string;
  /** Name of the account (`config.accounts`) the webhook belongs to; the default account when absent. */
  account?: string;
  /**
   * The URL the provider called: absolute, or the path and query. Providers that sign the URL (Twilio) or
   * put data in it need it.
   */
  url?: string;
}

export interface Driver<M extends BaseMessage = BaseMessage> {
  readonly name: string;
  readonly channel: Channel;
  readonly capabilities: DriverCapabilities;

  send(message: M, context: SendContext): Promise<SendResult>;
  sendBatch?(messages: M[], contexts: SendContext[]): Promise<SendResult[]>;

  verifyWebhook?(req: WebhookRequest): boolean | Promise<boolean>;
  parseWebhook?(req: WebhookRequest): RelayoEvent[] | Promise<RelayoEvent[]>;
}
